        /// <para>On Android you can directly specify the input type:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextinputAndroidInputtypeNumber">TextinputAndroidInputtypeNumber</see></description></item>
        /// <item><description>the text input type to use, overriding other properties. This is documented at https://developer.android.com/reference/android/text/InputType</description></item>
        /// </list>
        /// </remarks>
        /// <param name="window">the window to enable text input.</param>
        /// <param name="props">the properties to use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_StartTextInputWithProperties">SDL_StartTextInputWithProperties</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Keyboards.SetTextInputArea">SetTextInputArea</see></seealso>
        /// <seealso><see cref="CSDL.Input.Keyboards.StartTextInput">StartTextInput</see></seealso>
        /// <seealso><see cref="CSDL.Input.Keyboards.StopTextInput">StopTextInput</see></seealso>
        /// <seealso><see cref="CSDL.Input.Keyboards.TextInputActive">TextInputActive</see></seealso>
        public static extern void StartTextInputWithProperties();

        /// <summary>
        /// <para>Stop receiving any text input events in a window.</para>
        /// </summary>
        /// <remarks>
        /// <para>If <see cref="CSDL.Input.Keyboards.StartTextInput">StartTextInput</see> showed the screen keyboard, this function will hide it.</para>
        /// </remarks>
        /// <param name="window">the window to disable text input.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_StopTextInput">SDL_StopTextInput</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Keyboards.StartTextInput">StartTextInput</see></seealso>
        public static extern void StopTextInput();

        /// <summary>
        /// <para>Check whether or not Unicode text input events are enabled for a window.</para>
        /// </summary>
        /// <param name="window">the window to check.</param>
        /// <returns>
        /// <para>(bool) Returns true if text input events are enabled else false.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_TextInputActive">SDL_TextInputActive</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Keyboards.StartTextInput">StartTextInput</see></seealso>
        public static extern void TextInputActive();
    }
